'use strict';

const CANONICAL_UINT = /^(?:0|[1-9][0-9]*)$/;
const KEY_RE = /^[A-Z][A-Z0-9_]*$/;

const SCHEMA = ['WINDOW', 'RATE', 'LIMIT', 'COLOR'];
const REQUIRED = ['WINDOW', 'RATE', 'LIMIT'];
const INT_RANGES = {
  WINDOW: [2, 20],
  RATE: [0, 30],
  LIMIT: [1, 125],
};
const COLOR_VALUES = ['red', 'blue'];

function isTerminator(c) {
  return c === '\n' || c === '\r';
}

// Length of the record terminator starting at index i (1 for LF/CR, 2 for CRLF).
function terminatorLength(text, i) {
  if (text[i] === '\r' && text[i + 1] === '\n') return 2;
  return 1;
}

// Split the input into records, where each record is a list of raw (decoded)
// field strings. Throws INVALID_FORMAT on lexical problems (bad quoting).
function splitRecords(text) {
  const records = [];
  const n = text.length;
  let i = 0;

  while (i < n) {
    const fields = [];
    let recordDone = false;

    while (!recordDone) {
      if (i < n && text[i] === '"') {
        // Whole field is double quoted, including its KEY=VALUE text.
        i++;
        let raw = '';
        let closed = false;
        while (i < n) {
          const c = text[i];
          if (c === '"') {
            if (text[i + 1] === '"') {
              raw += '"';
              i += 2;
              continue;
            }
            i++;
            closed = true;
            break;
          }
          raw += c;
          i++;
        }
        if (!closed) throw new Error('INVALID_FORMAT');
        fields.push(raw);
        if (i >= n) {
          recordDone = true;
          continue;
        }
        const c = text[i];
        if (c === ';') {
          i++;
          continue;
        }
        if (isTerminator(c)) {
          i += terminatorLength(text, i);
          recordDone = true;
          continue;
        }
        // Any other character after a closing quote is illegal.
        throw new Error('INVALID_FORMAT');
      }

      // Unquoted field: runs to the next separator or record ending.
      let raw = '';
      while (i < n) {
        const c = text[i];
        if (c === ';' || isTerminator(c)) break;
        if (c === '"') throw new Error('INVALID_FORMAT');
        raw += c;
        i++;
      }
      fields.push(raw);
      if (i >= n) {
        recordDone = true;
        continue;
      }
      const c = text[i];
      if (c === ';') {
        i++;
        continue;
      }
      i += terminatorLength(text, i);
      recordDone = true;
    }

    records.push(fields);
  }

  return records;
}

function decodeField(raw) {
  const eq = raw.indexOf('=');
  if (eq < 0) throw new Error('INVALID_FORMAT');
  if (raw.indexOf('=', eq + 1) !== -1) throw new Error('INVALID_FORMAT');
  const key = raw.slice(0, eq);
  if (!KEY_RE.test(key)) throw new Error('INVALID_FORMAT');
  const value = raw.slice(eq + 1).trim();
  return [key, value];
}

function parseRecord(fields) {
  // Phase 1: syntax + duplicate validation for the whole record.
  const decoded = new Map();
  for (const raw of fields) {
    const [key, value] = decodeField(raw);
    if (decoded.has(key)) throw new Error('INVALID_FORMAT');
    decoded.set(key, value);
  }

  // Phase 2: semantic validation.
  for (const key of REQUIRED) {
    if (!decoded.has(key)) throw new Error('INVALID_VALUE');
  }

  const out = {};
  for (const key of SCHEMA) {
    if (!decoded.has(key)) continue;
    const value = decoded.get(key);
    if (key === 'COLOR') {
      if (COLOR_VALUES.indexOf(value) === -1) throw new Error('INVALID_VALUE');
      out[key] = value;
    } else {
      const [min, max] = INT_RANGES[key];
      if (!CANONICAL_UINT.test(value)) throw new Error('INVALID_VALUE');
      const num = Number(value);
      if (!Number.isSafeInteger(num) || num < min || num > max) {
        throw new Error('INVALID_VALUE');
      }
      out[key] = num;
    }
  }

  return out;
}

function readInput(text) {
  if (typeof text !== 'string') throw new Error('INVALID_FORMAT');
  if (text === '') return [];
  const records = splitRecords(text);
  return records.map(parseRecord);
}

module.exports = { readInput };
